const crypto = require('crypto');

// Extraer firma del header
const signature = $input.headers['x-hub-signature'];
if (!signature) {
  throw new Error('Missing X-Hub-Signature header');
}

// Obtener secret del partner (en producción, hacer lookup a DB)
const secret = $env.PARTNER_SECRET || 'test_secret';

// Verificar firma
const body = JSON.stringify($input.body);
const expectedSig = crypto
  .createHmac('sha256', secret)
  .update(body)
  .digest('hex');

const receivedSig = signature.split(':')[1];

if (expectedSig !== receivedSig) {
  throw new Error('Invalid HMAC signature');
}

return { 
  valid: true,
  event: $input.body.event,
  source: $input.body.source,
  payload: $input.body.payload,
  trace_id: $input.body.trace_id
};

// Normalizar evento según tipo
const event = $input.body.event;
const payload = $input.body.payload;

let action = {};

switch(event) {
  case 'tour.purchased':
    action = {
      endpoint: '/api/orders',
      method: 'POST',
      data: {
        booking_reference: payload.booking_reference,
        service: 'tour',
        provider: $input.body.source,
        amount: payload.price
      }
    };
    break;

  case 'service.activated':
    action = {
      endpoint: '/api/reservas/' + payload.booking_id + '/add-service',
      method: 'POST',
      data: {
        service_id: payload.service_id,
        activated_by: 'partner',
        partner_name: $input.body.source
      }
    };
    break;

  default:
    throw new Error(`Unknown event type: ${event}`);
}

return { action, event, payload };

// Responder ACK al partner
return {
  ack: true,
  trace_id: $input.body.trace_id,
  event: $input.body.event,
  status: 'processed',
  timestamp: new Date().toISOString()
};
